int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_sb_info *info = sb->s_fs_info;
    struct shmem_options new_opts;
    int error;

    error = parse_shmem_options(data, &new_opts);
    if (error)
        return error;

    down_write(&sb->s_umount);
    if (info->users > 0 &&
        (info->max_blocks > new_opts.max_blocks ||
         info->max_inodes > new_opts.max_inodes)) {
        up_write(&sb->s_umount);
        return -EINVAL;
    }

    info->max_blocks = new_opts.max_blocks;
    info->max_inodes = new_opts.max_inodes;
    info->free_inodes += new_opts.free_inodes;
    if (new_opts.flags & SHMEM_REMOUNT_MPOL)
        info->policy = new_opts.policy;

    up_write(&sb->s_umount);
    return 0;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config config;
    int ret = 0;

    if (parse_shmem_options(data, &config) < 0)
        return -EINVAL;

    spin_lock(&sb->s_lock);

    if (sb->s_bdev && sb->s_bdev->bd_disk && sb->s_bdev->bd_disk->d_unmask) {
        if (sb->s_blocks_used > config.max_blocks) {
            spin_unlock(&sb->s_lock);
            return -ENOSPC;
        }
        if (sb->s_inodes_used > config.max_inodes) {
            spin_unlock(&sb->s_lock);
            return -ENOSPC;
        }
    }

    sb->s_max_blocks = config.max_blocks;
    sb->s_max_inodes = config.max_inodes;
    sb->s_free_inodes = config.max_inodes;

    if (config.set_policy) {
        mempolicy_parse(sb->s_mpol, config.policy_string);
    }

    spin_unlock(&sb->s_lock);

    return ret;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_options new_opts;
    int ret = 0;

    if (parse_shmem_options(data, &new_opts))
        return -EINVAL;

    spin_lock(&sb->s_lock);

    if (shmem_used_blocks(sb) > new_opts.max_blocks ||
        shmem_used_inodes(sb) > new_opts.max_inodes) {
        spin_unlock(&sb->s_lock);
        return -EINVAL;
    }

    sb->s_max_blocks = new_opts.max_blocks;
    sb->s_max_inodes = new_opts.max_inodes;
    sb->s_free_inodes = sb->s_max_inodes - shmem_used_inodes(sb);

    if (new_opts.flags & SHMEM_OPT_MEMORY_POLICY)
        set_memory_policy(sb, new_opts.policy);

    spin_unlock(&sb->s_lock);

    return ret;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config new_config;
    int result;

    result = parse_shmem_options(data, &new_config);
    if (result < 0)
        return result;

    spin_lock(&sb->s_lock);

    if (sb->s_bdev && (new_config.max_blocks < sb->s_blocks_used ||
                       new_config.max_inodes < sb->s_inodes_used)) {
        spin_unlock(&sb->s_lock);
        return -EINVAL;
    }

    sb->s_max_blocks = new_config.max_blocks;
    sb->s_max_inodes = new_config.max_inodes;
    sb->s_free_inodes = new_config.max_inodes;

    if (new_config.mpol) {
        mpol_put(sb->s_mpol);
        sb->s_mpol = mpol_get(new_config.mpol);
    }

    spin_unlock(&sb->s_lock);

    return 0;
}

int remount_shmem_config(struct super_block *sb, int *flags, char *data) {
    struct shmem_config config;
    int ret = 0;

    if (parse_shmem_options(data, &config) < 0)
        return -EINVAL;

    spin_lock(&sb->s_lock);

    if (sb->s_magic != SHMEM_FS_MAGIC || sb->s_blocks > config.max_blocks ||
        sb->s_inodes > config.max_inodes) {
        spin_unlock(&sb->s_lock);
        return -EBUSY;
    }

    sb->s_max_blocks = config.max_blocks;
    sb->s_max_inodes = config.max_inodes;
    sb->s_free_inodes = config.max_inodes;

    if (config.use_mpol)
        update_shmem_mpol(sb, config.mpol);

    spin_unlock(&sb->s_lock);

    return ret;
}
